    enonce: "<span dir=\"ltr\" class=\"expr pt\">ABE</span> مثلّث قائم الزاوية في <span dir=\"ltr\" class=\"expr pt\">E</span> بحيث <span dir=\"ltr\" class=\"expr pt\">AE = 8</span> و <span dir=\"ltr\" class=\"expr pt\">EB = 9.</span><br><svg class=\"figure\" direction=\"ltr\" viewBox=\"0 0 124 144\" width=\"124\" height=\"144\" xmlns=\"http://www.w3.org/2000/svg\"><g transform=\"translate(-29.4 -21.9)\"><line x1=\"130.0\" y1=\"140.0\" x2=\"50.0\" y2=\"140.0\" stroke=\"#2c3e50\" stroke-width=\"1.7\"/><line x1=\"50.0\" y1=\"140.0\" x2=\"50.0\" y2=\"50.0\" stroke=\"#2c3e50\" stroke-width=\"1.7\"/><line x1=\"50.0\" y1=\"50.0\" x2=\"130.0\" y2=\"140.0\" stroke=\"#2c3e50\" stroke-width=\"1.7\"/><polyline points=\"61.0,140.0 61.0,129.0 50.0,129.0\" fill=\"none\" stroke=\"#c0392b\" stroke-width=\"1.3\"/><circle cx=\"50.0\" cy=\"140.0\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"40.0\" y=\"155.2\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">E</text><circle cx=\"130.0\" cy=\"140.0\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"143.1\" y=\"151.4\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">A</text><circle cx=\"50.0\" cy=\"50.0\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"43.9\" y=\"40.3\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">B</text></g></svg><br>أحسب المسافة <span dir=\"ltr\" class=\"expr pt\">AB.</span>",
