    enonce: "النّقط <span dir=\"ltr\" class=\"expr pt\">F</span> و <span dir=\"ltr\" class=\"expr pt\">G</span> و <span dir=\"ltr\" class=\"expr pt\">H</span> على استقامة واحدة، و كذلك <span dir=\"ltr\" class=\"expr pt\">E</span> و <span dir=\"ltr\" class=\"expr pt\">G</span> و <span dir=\"ltr\" class=\"expr pt\">D</span>،<br>و <span dir=\"ltr\" class=\"expr pt\">(EF) // (HD).</span><br><span dir=\"ltr\" class=\"expr pt\">GH = 18 cm</span> و <span dir=\"ltr\" class=\"expr pt\">GF = 12 cm</span> و <span dir=\"ltr\" class=\"expr pt\">GD = 24 cm</span> و <span dir=\"ltr\" class=\"expr pt\">HD = 30 cm.</span><br><svg class=\"figure\" direction=\"ltr\" viewBox=\"0 0 165 211\" width=\"165\" height=\"211\" xmlns=\"http://www.w3.org/2000/svg\"><g transform=\"translate(6.6 10.4)\"><line x1=\"64.6\" y1=\"171.0\" x2=\"19.0\" y2=\"110.2\" stroke=\"#2c3e50\" stroke-width=\"1.7\"/><line x1=\"133.0\" y1=\"110.2\" x2=\"64.6\" y2=\"19.0\" stroke=\"#2c3e50\" stroke-width=\"1.7\"/><line x1=\"19.0\" y1=\"110.2\" x2=\"133.0\" y2=\"110.2\" stroke=\"#2c3e50\" stroke-width=\"1.7\"/><line x1=\"64.6\" y1=\"171.0\" x2=\"64.6\" y2=\"19.0\" stroke=\"#2c3e50\" stroke-width=\"1.7\"/><circle cx=\"64.6\" cy=\"171.0\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"63.6\" y=\"190.0\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">E</text><circle cx=\"19.0\" cy=\"110.2\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"4.1\" y=\"116.0\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">F</text><circle cx=\"64.6\" cy=\"110.2\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"55.6\" y=\"126.2\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">G</text><circle cx=\"133.0\" cy=\"110.2\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"147.9\" y=\"115.6\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">H</text><circle cx=\"64.6\" cy=\"19.0\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"63.8\" y=\"8.0\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">D</text></g></svg><br><span dir=\"ltr\" class=\"expr\">1)</span> أحسب <span dir=\"ltr\" class=\"expr pt\">EG.</span><br><span dir=\"ltr\" class=\"expr\">2)</span> أحسب <span dir=\"ltr\" class=\"expr pt\">EF.</span>",
    correction: [{"quoi":"المعطيات","math":"<span dir=\"ltr\" class=\"expr pt\">GH = 18</span>  و  <span dir=\"ltr\" class=\"expr pt\">FG = 12</span>  و  <span dir=\"ltr\" class=\"expr pt\">DG = 24</span>  و  <span dir=\"ltr\" class=\"expr pt\">DH = 30</span>  و  <span dir=\"ltr\" class=\"expr pt\">(EF) // (DH)</span>"},{"quoi":"1)","math":"أحسب <span dir=\"ltr\" class=\"expr pt\">EG.</span>"},{"quoi":"في المثلّث GHD لنا","math":"<span dir=\"ltr\" class=\"expr pt\">(FE) // (HD)</span>  و  <span dir=\"ltr\" class=\"expr pt\">F ∈ (GH)</span>  و  <span dir=\"ltr\" class=\"expr pt\">E ∈ (GD)</span>"},{"quoi":"حسب نظرية طالس لنا","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\">GF</span><span class=\"den\">GH</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">GE</span><span class=\"den\">GD</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">FE</span><span class=\"den\">HD</span></span>"},{"quoi":"نعوّض","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\">12</span><span class=\"den\">18</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">EG</span><span class=\"den\">24</span></span>"},{"quoi":"إذن","math":"<span dir=\"ltr\" class=\"expr pt\">EG = 16</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr pt\">EG = 16</span>"},{"quoi":"2)","math":"أحسب <span dir=\"ltr\" class=\"expr pt\">EF.</span>"},{"quoi":"في المثلّث GHD لنا","math":"<span dir=\"ltr\" class=\"expr pt\">(FE) // (HD)</span>  و  <span dir=\"ltr\" class=\"expr pt\">F ∈ (GH)</span>  و  <span dir=\"ltr\" class=\"expr pt\">E ∈ (GD)</span>"},{"quoi":"حسب نظرية طالس لنا","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\">GF</span><span class=\"den\">GH</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">GE</span><span class=\"den\">GD</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">FE</span><span class=\"den\">HD</span></span>"},{"quoi":"نعوّض","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\">12</span><span class=\"den\">18</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">EF</span><span class=\"den\">30</span></span>"},{"quoi":"إذن","math":"<span dir=\"ltr\" class=\"expr pt\">EF = 20</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr pt\">EF = 20</span>"}],
    indice: "النّسبة GF/GH هي نفسها لـ EG/GD و EF/HD",
