    correction: [{"quoi":"المعطيات","math":"<span dir=\"ltr\" class=\"expr pt\">CR = 1,75</span>  و  <span dir=\"ltr\" class=\"expr pt\">CK = 3,5</span>  و  <span dir=\"ltr\" class=\"expr pt\">CS = 3,25</span>  و  <span dir=\"ltr\" class=\"expr pt\">(OR) // (KS)</span>"},{"quoi":"في المثلّث CKS لنا","math":"<span dir=\"ltr\" class=\"expr pt\">(RO) // (KS)</span>  و  <span dir=\"ltr\" class=\"expr pt\">R ∈ (CK)</span>  و  <span dir=\"ltr\" class=\"expr pt\">O ∈ (CS)</span>"},{"quoi":"حسب نظرية طالس لنا","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\">CR</span><span class=\"den\">CK</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">CO</span><span class=\"den\">CS</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">RO</span><span class=\"den\">KS</span></span>"},{"quoi":"نعوّض","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\">1,75</span><span class=\"den\">3,5</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">CO</span><span class=\"den\">3,25</span></span>"},{"quoi":"إذن","math":"<span dir=\"ltr\" class=\"expr pt\">CO = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">13</span><span class=\"den\">8</span></span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr pt\">CO = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">13</span><span class=\"den\">8</span></span>"}],
