    correction: [{"quoi":"المعطيات","math":"<span dir=\"ltr\" class=\"expr pt\">AT = 4,8</span>  و  <span dir=\"ltr\" class=\"expr pt\">HT = 3,2</span>  و  <span dir=\"ltr\" class=\"expr pt\">HS = 10</span>  و  <span dir=\"ltr\" class=\"expr pt\">(MT) // (HS)</span>"},{"quoi":"القاعدة","math":"إذا كانت النقطة <span dir=\"ltr\" class=\"expr pt\">B</span> بين <span dir=\"ltr\" class=\"expr pt\">A</span> و <span dir=\"ltr\" class=\"expr pt\">C</span> فإنّ <span dir=\"ltr\" class=\"expr pt\">AC = AB + BC</span>"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">AT = 4,8</span>  و  <span dir=\"ltr\" class=\"expr pt\">HT = 3,2</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">AH = 8</span>  ، لأنّ <span dir=\"ltr\" class=\"expr pt\">AH = 4,8 + 3,2</span>"},{"quoi":"في المثلّث ASH لنا","math":"<span dir=\"ltr\" class=\"expr pt\">(MT) // (SH)</span>  و  <span dir=\"ltr\" class=\"expr pt\">M ∈ (AS)</span>  و  <span dir=\"ltr\" class=\"expr pt\">T ∈ (AH)</span>"},{"quoi":"حسب نظرية طالس لنا","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\">AM</span><span class=\"den\">AS</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">AT</span><span class=\"den\">AH</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">MT</span><span class=\"den\">SH</span></span>"},{"quoi":"نعوّض","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\">4,8</span><span class=\"den\">8</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">MT</span><span class=\"den\">10</span></span>"},{"quoi":"إذن","math":"<span dir=\"ltr\" class=\"expr pt\">MT = 6</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr pt\">MT = 6</span>"}],
