    correction: [{"quoi":"المعطيات","math":"<span dir=\"ltr\" class=\"expr pt\">AB = 8</span>  و  <span dir=\"ltr\" class=\"expr pt\">AD = 7</span>  و  <span dir=\"ltr\" class=\"expr pt\">AC = 15</span>  و  <span dir=\"ltr\" class=\"expr pt\">BC = 17</span>  و  <span dir=\"ltr\" class=\"expr pt\">(DE) // (BC)</span>  و  <span dir=\"ltr\" class=\"expr pt\">(EF) // (AB)</span>"},{"quoi":"1)","math":"أحسب <span dir=\"ltr\" class=\"expr pt\">AE.</span>"},{"quoi":"في المثلّث ABC لنا","math":"<span dir=\"ltr\" class=\"expr pt\">(DE) // (BC)</span>  و  <span dir=\"ltr\" class=\"expr pt\">D ∈ (AB)</span>  و  <span dir=\"ltr\" class=\"expr pt\">E ∈ (AC)</span>"},{"quoi":"حسب نظرية طالس لنا","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\">AD</span><span class=\"den\">AB</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">AE</span><span class=\"den\">AC</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">DE</span><span class=\"den\">BC</span></span>"},{"quoi":"نعوّض","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\">7</span><span class=\"den\">8</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">AE</span><span class=\"den\">15</span></span>"},{"quoi":"إذن","math":"<span dir=\"ltr\" class=\"expr pt\">AE = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">105</span><span class=\"den\">8</span></span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr pt\">AE = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">105</span><span class=\"den\">8</span></span>"},{"quoi":"2)","math":"استنتج <span dir=\"ltr\" class=\"expr pt\">CE.</span>"},{"quoi":"القاعدة","math":"إذا كانت النقطة <span dir=\"ltr\" class=\"expr pt\">B</span> بين <span dir=\"ltr\" class=\"expr pt\">A</span> و <span dir=\"ltr\" class=\"expr pt\">C</span> فإنّ <span dir=\"ltr\" class=\"expr pt\">AC = AB + BC</span>"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">AC = 15</span>  و  <span dir=\"ltr\" class=\"expr pt\">AE =</span> <span class=\"frac\" dir=\"ltr\"><span class=\"num\">105</span><span class=\"den\">8</span></span>  إذن  <span dir=\"ltr\" class=\"expr pt\">CE =</span> <span class=\"frac\" dir=\"ltr\"><span class=\"num\">15</span><span class=\"den\">8</span></span>  ، لأنّ <span dir=\"ltr\" class=\"expr pt\">CE = 15 −</span> <span class=\"frac\" dir=\"ltr\"><span class=\"num\">105</span><span class=\"den\">8</span></span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr pt\">CE = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">15</span><span class=\"den\">8</span></span>"},{"quoi":"3)","math":"أحسب <span dir=\"ltr\" class=\"expr pt\">CF.</span>"},{"quoi":"في المثلّث CAB لنا","math":"<span dir=\"ltr\" class=\"expr pt\">(EF) // (AB)</span>  و  <span dir=\"ltr\" class=\"expr pt\">E ∈ (CA)</span>  و  <span dir=\"ltr\" class=\"expr pt\">F ∈ (CB)</span>"},{"quoi":"حسب نظرية طالس لنا","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\">CE</span><span class=\"den\">CA</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">CF</span><span class=\"den\">CB</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">EF</span><span class=\"den\">AB</span></span>"},{"quoi":"نعوّض","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\"><span class=\"frac\" dir=\"ltr\"><span class=\"num\">15</span><span class=\"den\">8</span></span><span dir=\"ltr\" class=\"expr pt\">&lt;/span&gt;&lt;span class=\"den\"&gt;15&lt;/span&gt;&lt;/span&gt; = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">CF</span><span class=\"den\">17</span></span>"},{"quoi":"إذن","math":"<span dir=\"ltr\" class=\"expr pt\">CF = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">17</span><span class=\"den\">8</span></span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr pt\">CF = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">17</span><span class=\"den\">8</span></span>"},{"quoi":"4)","math":"استنتج <span dir=\"ltr\" class=\"expr pt\">BF.</span>"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">BC = 17</span>  و  <span dir=\"ltr\" class=\"expr pt\">CF =</span> <span class=\"frac\" dir=\"ltr\"><span class=\"num\">17</span><span class=\"den\">8</span></span>  إذن  <span dir=\"ltr\" class=\"expr pt\">BF =</span> <span class=\"frac\" dir=\"ltr\"><span class=\"num\">119</span><span class=\"den\">8</span></span>  ، لأنّ <span dir=\"ltr\" class=\"expr pt\">BF = 17 −</span> <span class=\"frac\" dir=\"ltr\"><span class=\"num\">17</span><span class=\"den\">8</span></span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr pt\">BF = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">119</span><span class=\"den\">8</span></span>"}],
